parameters.query:
select *
from public.cancel_appointment(
  $1::uuid
);

conditions.leftValue:
={{
  $('Classify Client Reply').first().json.output.intent === 'neutral'
  &&
  $('Normalize Message Input').first().json.text.trim().length >= 2
  &&
  $('Normalize Message Input').first().json.text.trim().length <= 100
  &&
  $('Normalize Message Input').first().json.text.trim().split(/\s+/).length <= 5
  &&
  /^[\p{L}\p{M}][\p{L}\p{M}\s.'-]*$/u.test(
    $('Normalize Message Input').first().json.text.trim()
  )
}}

={{
  (() => {
    const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    const action = String($json.action || '');
    const id = String($json.lead_id || '');

    if (action === 'book') {
      return uuid.test(id);
    }

    if (['send', 'delay', 'close'].includes(action)) {
      return uuid.test(id)
        && /^[1-9]\d*$/.test(String($json.followup_version || ''));
    }

    if (action === 'slot') {
      return uuid.test(id)
        && /^\d{10}$/.test(String($json.slot_unix || ''));
    }

    if ([
      'cancel_appt',
      'reschedule_appt',
      'appt_completed',
      'appt_no_show',
      'send_no_show_fu',
      'manager_cancel_appt'
    ].includes(action)) {
      return uuid.test(String($json.appointment_id || ''));
    }

    if (action === 'handoff_close') {
      return uuid.test(String($json.handoff_id || ''));
    }

    return false;
  })()
}}
